package com.megaiptv.eltv;

import android.os.Bundle;
import android.view.ViewGroup;

import androidx.fragment.app.FragmentActivity;

/**
 * Activité de base pour toutes les activités de l'application SAUF PlaybackActivity.
 *
 * Gère l'overlay mini-player global :
 *  - Injecte le layout mini_player_overlay dans android.R.id.content
 *  - Attache / détache le PlayerView selon le cycle de vie
 *  - Garantit qu'un seul PlayerView est attaché à l'ExoPlayer à la fois
 */
public abstract class BaseActivity extends FragmentActivity {

    private MiniPlayerController miniPlayer;
    private boolean              overlayAttached = false;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
    }

    /**
     * onStart est appelé après que le contenu de l'activité est visible.
     * On injecte le mini-player ici pour qu'il s'applique quel que soit
     * le chemin de création (setContentView ou GuidedStep.addAsRoot).
     */
    @Override
    protected void onStart() {
        super.onStart();
        if (!overlayAttached) {
            attachMiniPlayerOverlay();
        }
    }

    /** Met à jour le mini-player quand l'activité reprend le premier plan. */
    @Override
    protected void onResume() {
        super.onResume();
        if (miniPlayer != null) miniPlayer.update();
    }

    /**
     * Détache le PlayerView du mini-player avant de passer en arrière-plan.
     * Permet à PlaybackActivity de s'attacher librement sans conflit.
     */
    @Override
    protected void onPause() {
        super.onPause();
        if (miniPlayer != null) miniPlayer.detachView();
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        if (miniPlayer != null) {
            miniPlayer.destroy();
            miniPlayer = null;
        }
    }

    // ─── Injection de l'overlay ───────────────────────────────────────────────

    private void attachMiniPlayerOverlay() {
        try {
            ViewGroup contentRoot = getWindow().getDecorView()
                    .getRootView().findViewById(android.R.id.content);
            if (contentRoot == null) return;

            android.view.View overlay = getLayoutInflater()
                    .inflate(R.layout.mini_player_overlay, contentRoot, false);
            contentRoot.addView(overlay);

            miniPlayer      = new MiniPlayerController(this, overlay);
            overlayAttached = true;
        } catch (Exception ignored) {
            // Ne pas faire planter l'activité si l'overlay échoue
        }
    }
}

package com.megaiptv.eltv;

import android.os.Bundle;
import android.view.KeyEvent;
import android.view.View;

import androidx.fragment.app.FragmentActivity;

/**
 * Activité de base pour toutes les activités de l'application SAUF PlaybackActivity.
 *
 * Gestion du mini-player :
 *  - Le mini-player est INTÉGRÉ dans le layout de chaque activité fille (pas d'overlay flottant)
 *  - {@link #setupMiniPlayer()} initialise {@link MiniPlayerController} sur les vues du layout
 *  - {@link #dispatchKeyEvent} permet la navigation D-PAD vers/depuis le mini-player :
 *      · DPAD_UP  depuis le contenu → mini-player play/pause quand focus bloqué en haut
 *      · DPAD_DOWN depuis mini-player → retour au contenu
 *      · MEDIA_PLAY_PAUSE partout → bascule play/pause
 */
public abstract class BaseActivity extends FragmentActivity {

    /** Contrôleur du mini-player intégré dans le layout de l'activité. */
    protected MiniPlayerController miniPlayerController;

    // ─── Cycle de vie ─────────────────────────────────────────────────────────

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
    }

    /**
     * Initialise le {@link MiniPlayerController} en cherchant les vues
     * à partir de la DecorView (qui contient le layout de l'activité).
     * À appeler APRÈS {@code setContentView()} dans les sous-classes.
     */
    protected void setupMiniPlayer() {
        try {
            miniPlayerController = new MiniPlayerController(this, getWindow().getDecorView());
        } catch (Exception ignored) {}
    }

    @Override
    protected void onResume() {
        super.onResume();
        if (miniPlayerController != null) miniPlayerController.update();
    }

    @Override
    protected void onPause() {
        super.onPause();
        if (miniPlayerController != null) miniPlayerController.detachView();
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        if (miniPlayerController != null) {
            miniPlayerController.destroy();
            miniPlayerController = null;
        }
    }

    // ─── Navigation D-PAD vers le mini-player ────────────────────────────────

    /**
     * Retourne le conteneur du fragment principal (BrowseFragment, DetailsFragment…).
     * Surcharger dans chaque sous-classe pour permettre le retour du focus
     * depuis le mini-player vers le contenu principal.
     */
    protected View getContentFragmentContainer() {
        return null;
    }

    /**
     * Intercept D-PAD pour rendre le mini-player accessible :
     *
     * <ul>
     *   <li>DPAD_UP  : si le focus ne peut plus monter dans le contenu Leanback
     *       (il reste sur la même vue), on transfert le focus au bouton ▶/⏸.</li>
     *   <li>DPAD_DOWN : si le mini-player a le focus, retour au contenu principal.</li>
     *   <li>MEDIA_PLAY_PAUSE : bascule lecture/pause partout.</li>
     * </ul>
     */
    @Override
    public boolean dispatchKeyEvent(KeyEvent event) {
        if (event.getAction() != KeyEvent.ACTION_DOWN) {
            return super.dispatchKeyEvent(event);
        }

        int key = event.getKeyCode();

        // ── Touche média play/pause (télécommande) ──────────────────────────
        if (key == KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE
                || key == KeyEvent.KEYCODE_MEDIA_PLAY
                || key == KeyEvent.KEYCODE_MEDIA_PAUSE) {
            PlayerManager pm = PlayerManager.getInstance();
            if (pm.hasStream()) {
                if (pm.isPlaying()) pm.pause(); else pm.resume();
                if (miniPlayerController != null) miniPlayerController.update();
                return true;
            }
        }

        // ── Navigation vers / depuis le mini-player ─────────────────────────
        View container = findViewById(R.id.mini_player_container);
        boolean miniVisible = container != null
                && container.getVisibility() == View.VISIBLE;

        if (!miniVisible) return super.dispatchKeyEvent(event);

        boolean miniHasFocus = container.hasFocus();

        if (!miniHasFocus && key == KeyEvent.KEYCODE_DPAD_UP) {
            // Laisse Leanback gérer d'abord ; si le focus ne bouge pas
            // (on est déjà tout en haut du contenu), on saute au mini-player.
            View before = getCurrentFocus();
            boolean handled = super.dispatchKeyEvent(event);
            View after = getCurrentFocus();
            if (after == before || after == null) {
                View btn = findViewById(R.id.mini_play_pause_btn);
                if (btn != null) {
                    btn.requestFocus();
                    return true;
                }
            }
            return handled;
        }

        if (miniHasFocus && key == KeyEvent.KEYCODE_DPAD_DOWN) {
            // Retour au contenu principal
            boolean handled = super.dispatchKeyEvent(event);
            if (container.hasFocus()) {
                // Le focus n'a pas quitté le mini-player → on le force vers le contenu
                View content = getContentFragmentContainer();
                if (content != null) {
                    content.requestFocus();
                    return true;
                }
            }
            return handled;
        }

        return super.dispatchKeyEvent(event);
    }
}

package com.megaiptv.eltv;

import android.os.Bundle;

public class DetailsActivity extends BaseActivity {

    public static final String CHANNEL = "channel";

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_details);
        if (savedInstanceState == null) {
            getSupportFragmentManager().beginTransaction()
                    .replace(R.id.details_fragment, new VideoDetailsFragment())
                    .commit();
        }
    }

}

package com.megaiptv.eltv;

import android.os.Bundle;
import android.view.View;

/**
 * Activité d'affichage des détails d'une chaîne.
 *
 * Mini-player docké en haut à droite, intégré dans activity_details.xml.
 * Accessible via D-PAD : presser UP depuis le contenu pour y accéder,
 * DOWN depuis le mini-player pour revenir aux détails.
 */
public class DetailsActivity extends BaseActivity {

    public static final String CHANNEL = "channel";

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_details);

        // Mini-player intégré dans activity_details.xml (pas d'overlay flottant)
        setupMiniPlayer();

        if (savedInstanceState == null) {
            getSupportFragmentManager().beginTransaction()
                    .replace(R.id.details_fragment, new VideoDetailsFragment())
                    .commit();
        }
    }

    /** Permet à dispatchKeyEvent de BaseActivity de retourner le focus vers les détails. */
    @Override
    protected View getContentFragmentContainer() {
        return findViewById(R.id.details_fragment);
    }
}

package com.megaiptv.eltv;

import android.app.Activity;
import android.app.Application;
import android.os.Bundle;

import androidx.annotation.NonNull;

/**
 * Application globale : surveille le cycle de vie de toutes les activités.
 *
 * Logique de comptage (onStart / onStop) :
 *   - Navigation interne (A → B) : count passe 1 → 2 → 1  (jamais 0)
 *   - App mise en arrière-plan    : count passe 1 → 0 → STOP
 *   - Retour au premier plan      : count passe 0 → 1 → mini-player se met à jour
 *
 * Ainsi le stream s'arrête automatiquement quand l'utilisateur appuie sur
 * Home, bascule vers une autre application (Netflix, etc.) ou éteint l'écran.
 */
public class ELTVApplication extends Application {

    /** Nombre d'activités actuellement en état "démarré" (entre onStart et onStop). */
    private int startedCount = 0;

    @Override
    public void onCreate() {
        super.onCreate();

        registerActivityLifecycleCallbacks(new ActivityLifecycleCallbacks() {

            @Override
            public void onActivityStarted(@NonNull Activity activity) {
                startedCount++;
            }

            @Override
            public void onActivityStopped(@NonNull Activity activity) {
                // Ignorer les changements de configuration (rotation, etc.)
                if (activity.isChangingConfigurations()) return;

                startedCount = Math.max(0, startedCount - 1);

                if (startedCount == 0) {
                    // Aucune activité en premier plan → app en arrière-plan
                    // Arrêt immédiat du stream
                    PlayerManager.getInstance().release();
                }
            }

            // ── Callbacks non utilisés ─────────────────────────────────────
            @Override public void onActivityCreated(@NonNull Activity a, Bundle b) {}
            @Override public void onActivityResumed(@NonNull Activity a) {}
            @Override public void onActivityPaused(@NonNull Activity a) {}
            @Override public void onActivitySaveInstanceState(@NonNull Activity a, @NonNull Bundle b) {}
            @Override public void onActivityDestroyed(@NonNull Activity a) {}
        });
    }
}

package com.megaiptv.eltv;

import android.os.Bundle;

public class MainActivity extends BaseActivity implements ThemeManager.ThemeChangeListener {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        ThemeManager.getInstance().init(this);
        ThemeManager.getInstance().addListener(this);
        setContentView(R.layout.activity_main);
        if (savedInstanceState == null) {
            getSupportFragmentManager().beginTransaction()
                    .replace(R.id.main_browse_fragment, new MainFragment())
                    .commit();
        }
    }

    @Override
    public void onThemeChanged(int theme) {
        // MainFragment se met à jour via son propre listener
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        ThemeManager.getInstance().removeListener(this);
    }
}

package com.megaiptv.eltv;

