        // MainFragment se met à jour via son propre listener
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        ThemeManager.getInstance().removeListener(this);
    }
}

package com.megaiptv.eltv;

import android.app.Activity;
import android.content.Intent;
import android.view.View;
import android.widget.TextView;

import androidx.media3.exoplayer.ExoPlayer;
import androidx.media3.ui.PlayerView;

/**
 * Contrôle le mini-player overlay présent dans toutes les activités
 * sauf PlaybackActivity (qui est la vue plein écran).
 *
 * Stratégie de partage du player :
 *   - Un seul ExoPlayer singleton (PlayerManager)
 *   - Quand PlaybackActivity est au premier plan → PlayerView full screen s'attache au player
 *     (Media3 détache automatiquement le mini-player)
 *   - Quand l'utilisateur revient → BaseActivity.onResume() réattache le mini-player
 */
public class MiniPlayerController {

    private final Activity    activity;
    private final View        container;
    private final PlayerView  playerView;
    private final TextView    channelName;

    public MiniPlayerController(Activity activity, View overlayRoot) {
        this.activity    = activity;
        this.container   = overlayRoot.findViewById(R.id.mini_player_container);
        this.playerView  = overlayRoot.findViewById(R.id.mini_player_view);
        this.channelName = overlayRoot.findViewById(R.id.mini_channel_name);

        // Bouton plein écran
        overlayRoot.findViewById(R.id.mini_expand_btn).setOnClickListener(v -> expand());

        // Bouton stop
        overlayRoot.findViewById(R.id.mini_stop_btn).setOnClickListener(v -> stop());
    }

    // ─── API publique ─────────────────────────────────────────────────────────

    /**
     * Met à jour la visibilité et le contenu du mini-player.
     * À appeler dans onResume() de BaseActivity.
     */
    public void update() {
        ExoPlayer player = PlayerManager.getInstance().getPlayerIfExists();
        if (player != null && PlayerManager.getInstance().isStreamActive()) {
            container.setVisibility(View.VISIBLE);
            playerView.setPlayer(player);
            String name = PlayerManager.getInstance().getCurrentChannelName();
            channelName.setText(name != null ? name : "");
        } else {
            container.setVisibility(View.GONE);
            playerView.setPlayer(null);
        }
    }

    /**
     * Détache le PlayerView du player sans stopper la lecture.
     * À appeler dans onPause() pour éviter les conflits quand
     * PlaybackActivity prend le premier plan.
     */
    public void detachView() {
        playerView.setPlayer(null);
    }

    /** Libère les références — appelé dans onDestroy(). */
    public void destroy() {
        playerView.setPlayer(null);
    }

    // ─── Actions ──────────────────────────────────────────────────────────────

    private void expand() {
        String url  = PlayerManager.getInstance().getCurrentUrl();
        String name = PlayerManager.getInstance().getCurrentChannelName();
        if (url != null && !url.isEmpty()) {
            Intent intent = new Intent(activity, PlaybackActivity.class);
            intent.putExtra(PlaybackActivity.CHANNEL_URL,  url);
            intent.putExtra(PlaybackActivity.CHANNEL_NAME, name != null ? name : "");
            activity.startActivity(intent);
        }
    }

    private void stop() {
        PlayerManager.getInstance().release();
        container.setVisibility(View.GONE);
    }
}

package com.megaiptv.eltv;

import android.app.Activity;
import android.content.Intent;
import android.view.View;
import android.widget.TextView;

import androidx.media3.exoplayer.ExoPlayer;
import androidx.media3.ui.PlayerView;

/**
 * Contrôle le mini-player overlay présent dans toutes les activités
 * sauf PlaybackActivity (qui est la vue plein écran).
 *
 * Stratégie de partage du player :
 *   - Un seul ExoPlayer singleton (PlayerManager)
 *   - Quand PlaybackActivity est au premier plan → PlayerView full screen s'attache au player
 *     (Media3 détache automatiquement le mini-player)
 *   - Quand l'utilisateur revient → BaseActivity.onResume() réattache le mini-player
 */
public class MiniPlayerController {

    private final Activity   activity;
    private final View       container;
    private final PlayerView playerView;
    private final TextView   channelName;
    private final TextView   playPauseBtn;

    public MiniPlayerController(Activity activity, View overlayRoot) {
        this.activity     = activity;
        this.container    = overlayRoot.findViewById(R.id.mini_player_container);
        this.playerView   = overlayRoot.findViewById(R.id.mini_player_view);
        this.channelName  = overlayRoot.findViewById(R.id.mini_channel_name);
        this.playPauseBtn = overlayRoot.findViewById(R.id.mini_play_pause_btn);

        // Bouton play / pause
        if (playPauseBtn != null) {
            playPauseBtn.setOnClickListener(v -> togglePlayPause());
        }

        // Bouton plein écran
        View expandBtn = overlayRoot.findViewById(R.id.mini_expand_btn);
        if (expandBtn != null) expandBtn.setOnClickListener(v -> expand());

        // Bouton stop
        View stopBtn = overlayRoot.findViewById(R.id.mini_stop_btn);
        if (stopBtn != null) stopBtn.setOnClickListener(v -> stop());
    }

    // ─── API publique ─────────────────────────────────────────────────────────

    /**
     * Met à jour la visibilité et le contenu du mini-player.
     * À appeler dans onResume() de BaseActivity.
     */
    public void update() {
        PlayerManager pm = PlayerManager.getInstance();
        ExoPlayer player = pm.getPlayerIfExists();
        if (player != null && (pm.isStreamActive() || pm.hasStream())) {
            container.setVisibility(View.VISIBLE);
            playerView.setPlayer(player);
            String name = pm.getCurrentChannelName();
            channelName.setText(name != null ? name : "");
            refreshPlayPauseIcon();
        } else {
            container.setVisibility(View.GONE);
            playerView.setPlayer(null);
        }
    }

    /**
     * Détache le PlayerView du player sans stopper la lecture.
     * À appeler dans onPause() pour éviter les conflits quand
     * PlaybackActivity prend le premier plan.
     */
    public void detachView() {
        playerView.setPlayer(null);
    }

    /** Libère les références — appelé dans onDestroy(). */
    public void destroy() {
        playerView.setPlayer(null);
    }

    // ─── Actions ──────────────────────────────────────────────────────────────

    private void togglePlayPause() {
        PlayerManager pm = PlayerManager.getInstance();
        if (pm.isPlaying()) {
            pm.pause();
        } else {
            pm.resume();
        }
        refreshPlayPauseIcon();
    }

    private void refreshPlayPauseIcon() {
        if (playPauseBtn == null) return;
        playPauseBtn.setText(PlayerManager.getInstance().isPlaying() ? "⏸" : "▶");
    }

    private void expand() {
        String url  = PlayerManager.getInstance().getCurrentUrl();
        String name = PlayerManager.getInstance().getCurrentChannelName();
        if (url != null && !url.isEmpty()) {
            Intent intent = new Intent(activity, PlaybackActivity.class);
            intent.putExtra(PlaybackActivity.CHANNEL_URL,  url);
            intent.putExtra(PlaybackActivity.CHANNEL_NAME, name != null ? name : "");
            activity.startActivity(intent);
        }
    }

    private void stop() {
        PlayerManager.getInstance().release();
        container.setVisibility(View.GONE);
    }
}

package com.megaiptv.eltv;

import android.os.Bundle;

import androidx.fragment.app.FragmentActivity;

public class PlaybackActivity extends FragmentActivity {

    public static final String CHANNEL_URL  = "channel_url";
    public static final String CHANNEL_NAME = "channel_name";

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_playback);
        if (savedInstanceState == null) {
            getSupportFragmentManager().beginTransaction()
                    .replace(R.id.playback_container, new PlaybackVideoFragment())
                    .commit();
        }
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        if (isFinishing()) {
            PlayerManager.getInstance().release();
        }
    }
}

package com.megaiptv.eltv;

import android.os.Bundle;

import androidx.fragment.app.FragmentActivity;

public class PlaybackActivity extends FragmentActivity {

    public static final String CHANNEL_URL  = "channel_url";
    public static final String CHANNEL_NAME = "channel_name";

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_playback);
        if (savedInstanceState == null) {
            getSupportFragmentManager().beginTransaction()
                    .replace(R.id.playback_container, new PlaybackVideoFragment())
                    .commit();
        }
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        // Ne PAS libérer le player ici : le flux continue dans le mini-player
        // quand l'utilisateur revient en arrière.
        // La libération explicite se fait uniquement via le bouton "Stop" du mini-player.
    }
}

package com.megaiptv.eltv;

import android.content.Context;

import androidx.media3.common.MediaItem;
import androidx.media3.common.Player;
import androidx.media3.datasource.DefaultDataSource;
import androidx.media3.datasource.okhttp.OkHttpDataSource;
import androidx.media3.exoplayer.ExoPlayer;
import androidx.media3.exoplayer.source.DefaultMediaSourceFactory;

public class PlayerManager {

    private static PlayerManager instance;
    private ExoPlayer player;

    // Métadonnées du flux en cours (utilisées par le mini-player)
    private String currentUrl;
    private String currentChannelName;

    public static PlayerManager getInstance() {
        if (instance == null) instance = new PlayerManager();
        return instance;
    }

    // ─── Création du player ───────────────────────────────────────────────────

    /**
     * Crée (ou retourne) le player ExoPlayer singleton.
     * Utilise OkHttp comme couche réseau : SSL étendu + timeout 30 s.
     */
    public ExoPlayer getPlayer(Context context) {
        if (player == null) {
            OkHttpDataSource.Factory okHttpFactory =
                    new OkHttpDataSource.Factory(NetworkUtils.getClient());
            DefaultDataSource.Factory dataSourceFactory =
                    new DefaultDataSource.Factory(context.getApplicationContext(), okHttpFactory);

            player = new ExoPlayer.Builder(context.getApplicationContext())
                    .setMediaSourceFactory(new DefaultMediaSourceFactory(dataSourceFactory))
                    .build();
        }
        return player;
    }

    /**
     * Retourne le player S'IL EXISTE déjà, sans en créer un nouveau.
     * Utilisé par le mini-player pour savoir si un flux est actif.
     */
    public ExoPlayer getPlayerIfExists() {
        return player;
    }

    // ─── Lecture ──────────────────────────────────────────────────────────────

    /** Lance la lecture et mémorise l'URL + le nom de la chaîne. */
    public void play(Context context, String url, String channelName) {
        this.currentUrl         = url;
        this.currentChannelName = channelName;

        ExoPlayer p = getPlayer(context);
        p.stop();
        p.clearMediaItems();
        p.setMediaItem(MediaItem.fromUri(url));
        p.prepare();
        p.play();
    }

    // ─── État ─────────────────────────────────────────────────────────────────

    /** Vrai si un flux est chargé et actif (lecture ou chargement). */
    public boolean isStreamActive() {
        if (player == null) return false;
        int state = player.getPlaybackState();
        return state == Player.STATE_READY || state == Player.STATE_BUFFERING;
    }

    public String getCurrentUrl()         { return currentUrl; }
    public String getCurrentChannelName() { return currentChannelName; }

    // ─── Libération ───────────────────────────────────────────────────────────

    /** Libère le player (appelé à la fermeture de PlaybackActivity). */
    public void release() {
        if (player != null) {
            player.release();
            player = null;
        }
        currentUrl         = null;
        currentChannelName = null;
    }
}

package com.megaiptv.eltv;

import android.content.Context;

import androidx.media3.common.MediaItem;
import androidx.media3.common.Player;
import androidx.media3.datasource.DefaultDataSource;
import androidx.media3.datasource.okhttp.OkHttpDataSource;
import androidx.media3.exoplayer.ExoPlayer;
import androidx.media3.exoplayer.source.DefaultMediaSourceFactory;

public class PlayerManager {

    private static PlayerManager instance;
    private ExoPlayer player;

    // Métadonnées du flux en cours (utilisées par le mini-player)
    private String currentUrl;
    private String currentChannelName;

    public static PlayerManager getInstance() {
        if (instance == null) instance = new PlayerManager();
        return instance;
    }

    // ─── Création du player ───────────────────────────────────────────────────

    /**
     * Crée (ou retourne) le player ExoPlayer singleton.
     * Utilise OkHttp comme couche réseau : SSL étendu + timeout 30 s.
     */
    public ExoPlayer getPlayer(Context context) {
        if (player == null) {
            OkHttpDataSource.Factory okHttpFactory =
                    new OkHttpDataSource.Factory(NetworkUtils.getClient());
            DefaultDataSource.Factory dataSourceFactory =
                    new DefaultDataSource.Factory(context.getApplicationContext(), okHttpFactory);

            player = new ExoPlayer.Builder(context.getApplicationContext())
                    .setMediaSourceFactory(new DefaultMediaSourceFactory(dataSourceFactory))
                    .build();
        }
        return player;
    }

    /**
     * Retourne le player S'IL EXISTE déjà, sans en créer un nouveau.
     * Utilisé par le mini-player pour savoir si un flux est actif.
     */
    public ExoPlayer getPlayerIfExists() {
        return player;
    }

    // ─── Lecture ──────────────────────────────────────────────────────────────

    /** Lance la lecture et mémorise l'URL + le nom de la chaîne. */
    public void play(Context context, String url, String channelName) {
        this.currentUrl         = url;
        this.currentChannelName = channelName;

        ExoPlayer p = getPlayer(context);
        p.stop();
        p.clearMediaItems();
        p.setMediaItem(MediaItem.fromUri(url));
        p.prepare();
        p.play();
    }

    // ─── Contrôle de la lecture ───────────────────────────────────────────────

    /** Met en pause la lecture sans libérer le player. */
    public void pause() {
        if (player != null) player.pause();
    }

    /** Reprend la lecture si elle était en pause. */
    public void resume() {
        if (player != null) player.play();
    }

    // ─── État ─────────────────────────────────────────────────────────────────

    /** Vrai si un flux est chargé et actif (lecture ou chargement). */
    public boolean isStreamActive() {
        if (player == null) return false;
        int state = player.getPlaybackState();
        return state == Player.STATE_READY || state == Player.STATE_BUFFERING;
    }

    /** Vrai si le player est en cours de lecture (pas en pause). */
    public boolean isPlaying() {
        return player != null && player.isPlaying();
    }

    /** Vrai si un flux a été chargé (même en pause). */
    public boolean hasStream() {
        return currentUrl != null && !currentUrl.isEmpty();
    }

    public String getCurrentUrl()         { return currentUrl; }
    public String getCurrentChannelName() { return currentChannelName; }

    // ─── Libération ───────────────────────────────────────────────────────────

    /** Libère le player (appelé à la fermeture de PlaybackActivity). */
    public void release() {
        if (player != null) {
            player.release();
            player = null;
        }
        currentUrl         = null;
        currentChannelName = null;
    }
}
